def digest(content: bytes) -> str:
    return hashlib.sha256(content.replace(b"\r\n", b"\n")).hexdigest()


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Проверить без изменений")
    args = parser.parse_args()
    root = Path(__file__).resolve().parent
    if not (root / "app/main.py").is_file() or not (root / "alembic.ini").is_file():
        print("Поместите установщик в корень Food_Porn рядом с launcher.py.")
        return 2
    if not (root / "app/miniapp/api.py").is_file():
        print("Сначала установите предыдущий Food_Porn_full_update_20260930.py.")
        return 2
    with zipfile.ZipFile(io.BytesIO(base64.b85decode(_DATA))) as archive:
        manifest = json.loads(archive.read("manifest.json"))
        changed = []
        conflicts = []
        warnings = []
        for name, rule in manifest.items():
            target = root / name
            if target.is_symlink():
                conflicts.append(f"{name}: символьная ссылка")
                continue
            content = archive.read(f"payload/{name}")
            if digest(content) != rule["sha256"]:
                print(f"Установщик повреждён: {name}")
                return 2
            if target.is_file():
                current = digest(target.read_bytes())
                if current == rule["sha256"]:
                    continue
                if current not in rule["previous"]:
                    (warnings if rule["optional"] else conflicts).append(name)
                    continue
            elif rule["previous"]:
                conflicts.append(f"{name}: файл отсутствует")
                continue
            changed.append(name)
        if conflicts:
            print("Локальная версия отличается; файлы не изменены. Конфликты:")
            for name in conflicts:
                print(" - " + name)
            print("Пришлите этот список для безопасной адаптации релиза к вашей версии.")
            return 2
        if warnings:
            print("Локальный тестовый файл отличается и останется без изменений: " + ", ".join(warnings))
        if not changed:
            print("Обновление уже установлено. Ничего менять не нужно.")
            return 0
        if args.check:
            print(f"Готово к установке: {len(changed)} файлов. Ничего не изменено.")
            for name in changed:
                print(("Обновить: " if (root/name).is_file() else "Добавить: ") + name)
            return 0
        backup = root / ("Food_Porn_7_photos_9_goals_backup_" + datetime.now().strftime("%Y%m%d_%H%M%S_%f"))
        originals = {}
        written = []
        try:
            for name in changed:
                target = root / name
                originals[name] = target.is_file()
                if originals[name]:
                    saved = backup / name
                    saved.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(target, saved)
                target.parent.mkdir(parents=True, exist_ok=True)
                stage = target.with_name(target.name + ".gift-update.tmp")
                try:
                    stage.write_bytes(archive.read(f"payload/{name}"))
                    stage.replace(target)
                finally:
                    stage.unlink(missing_ok=True)
                written.append(name)
        except Exception as exc:
            for name in reversed(written):
                if originals[name]:
                    shutil.copy2(backup/name, root/name)
                else:
                    (root/name).unlink(missing_ok=True)
            print(f"Установка отменена, файлы восстановлены: {exc}")
            return 1
        print(f"Установлено: {len(changed)} файлов. Резервная копия: {backup.name}")
        print("Запустите python -m pytest -q, затем перезапустите start_food_porn_miniapp.py.")
        print("Отправьте боту новый /start после запуска и используйте новую кнопку.")
        return 0


if __name__ == "__main__":
    sys.exit(main())
